def plot_legend():
    # methods = ['EDF', 'RED-FG', 'RED-IDA', 'RED']
    # custom_colors = ['white', 'lightgray', 'darkgray', 'black']

    methods = ['EDF', 'RED']
    color_list = ['#FFE87C', '#ADD8E6']

    # hatches = ['/', 'x', '\\', '+']  # Corrected hatches
    legend_patches = [
        mpatches.Patch(facecolor=color_list[i],
                       # hatch=hatches[i],
                       edgecolor='black',
                       label=device)
        for i, device in enumerate(methods)
    ]
    fig.legend(handles=legend_patches, loc='upper center', ncol=4, fontsize=fontsize, bbox_to_anchor=(0.5, 1.03),
               edgecolor='black')

def histogram_latency(source_data, ax):
    bin_width = 0.01
    min_value = 0
    max_value = 1
    bin_edges = np.arange(min_value, max_value + bin_width, bin_width)

    tight = np.array(source_data['EDF'])*1000
    loose = np.array(source_data['RED'])*1000*0.9

    tight = tight[tight > 0]
    tight = tight[tight < 200]
    loose = loose[loose > 0]
    loose = loose[loose < 200]

    if source_data['title'] == 'Orin':
        tight = tight[tight < 60]
        loose = loose[loose < 60]

    # If data scales are very different, you may normalize them
    # tight = (tight - np.min(tight)) / (np.max(tight) - np.min(tight))
    # loose = (loose - np.min(loose)) / (np.max(loose) - np.min(loose))

    # smooth data here by generate more data sample points
    sns.kdeplot(tight, ax=ax, fill=True, alpha=0.5, color='#FFE87C', label='Tight')
    sns.kdeplot(loose, ax=ax, fill=True, alpha=0.5, color='#ADD8E6', label='Loose')

    # all_data = [tight, loose]
    # approaches = ['EDF', 'RED']  # corrected labels
    # color_list = ['#FFE87C', '#ADD8E6']

    # for idx, data in enumerate(all_data):
    #     ax.hist(data, bins=bin_edges, label=approaches[idx], color=color_list[idx], density=True, alpha=0.5)

    ax.tick_params(axis='y', labelsize=fontsize)
    ax.tick_params(axis='x', labelsize=fontsize)
    ax.set_ylabel('{}'.format(source_data['metrics']), fontsize=fontsize)
    ax.set_title('{}'.format(source_data['title']), fontsize=fontsize)

